        Map<Long, String> personOpenings, boolean locked, Long added) {

    public static PeriodResponse from(Period period) {
        return from(period, Map.of(), null);
    }

    public static PeriodResponse from(Period period, Map<Long, BigDecimal> openings, Long added) {
        Map<Long, String> totals = new LinkedHashMap<>();
        period.personTotals().forEach((id, total) -> totals.put(id, total.toPlainString()));
        Map<Long, String> carried = new LinkedHashMap<>();
        period.personCarried().forEach((id, figure) -> carried.put(id, figure.toPlainString()));
        Map<Long, String> opening = new LinkedHashMap<>();
        openings.forEach((id, amount) -> opening.put(id, amount.toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(), period.closed(),
                period.closedTotal() == null ? null : period.closedTotal().toPlainString(), totals, carried, period.soft(), period.cap(),
                opening, period.locked(), added);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeriods {
    public void respond(@PathVariable("sheetId") String sheetId, Periods periods,
            ObjectResponse<List<PeriodResponse>> response) {
        // Each with its people's opening balances and the order it was added in.
        String sheet = sheetId.trim();
        Map<String, Map<Long, BigDecimal>> openings = periods.openings(sheet);
        Map<String, Long> added = periods.added(sheet);
        response.send(periods.list(sheet).stream()
                .map(p -> PeriodResponse.from(p, openings.getOrDefault(p.name(), Map.of()), added.get(p.name()))).toList());
    }
}
-- A claim's number becomes text: the sheet-wide 1, 2, ... or, while the sheet numbers by period, <period>-<n>
-- (X-<n> for a claim in no period). A correction names the number it corrects the same way.
-- claim_period_number_seq holds the last number each sheet gave in each period ('' is the no-period sequence).
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(300);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(300);
CREATE TABLE claim_period_number_seq (
    sheet_id    VARCHAR(255) NOT NULL,
    scope       VARCHAR(255) NOT NULL,
    last_number BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, scope)
);

